/* Product pages. Account and checkout flows are explicitly local previews. */
const productRoutes=['landing','signup','login','dashboard','profile','pricing','upgrade','checkout','confirmation','billing','premium'];
let account;try{account=JSON.parse(localStorage.getItem('studio-profile-v1'))}catch{account=null}let signedIn=sessionStorage.getItem('studio-demo-session')==='active'&&!!account;
let demoOrders;try{demoOrders=JSON.parse(localStorage.getItem('studio-demo-orders'))||[]}catch{demoOrders=[]}let annual=false,productRoute='landing',projectQuery='';
const productRoot=document.createElement('div');productRoot.id='productRoot';document.body.append(productRoot);
const routeLink=(route,text,cls='')=>`<a class="${cls}" href="#/${route}">${text}</a>`;
const logo=()=>`<a class="productBrand" href="#/landing"><span class="logo">E<span>↗</span></span><div>ENGINEERING<small>DESIGN STUDIO</small></div></a>`;
const initials=()=>esc((account?.name||'Your workspace').split(' ').slice(0,2).map(s=>s[0]).join('').toUpperCase());
const previewNotice=()=>'<div class="previewNotice"><span>◉</span><p><b>Account preview</b> · Profiles and sessions stay on this device. Production authentication and payments are not connected.</p></div>';
function publicHeader(){return `<nav class="publicNav" aria-label="Main navigation">${logo()}<div class="publicLinks">${routeLink('landing#features','The workspace')}${routeLink('pricing','Pricing')}${routeLink('dashboard','Explore studio')}</div><div class="publicNavActions">${routeLink(signedIn?'dashboard':'login',signedIn?'My dashboard':'Log in')}${routeLink(signedIn?'workspace':'signup',signedIn?'Open workspace ↗':'Get started ↗','pbutton primary')}</div></nav>`}
function publicFooter(){return `<footer class="publicFooter"><div>${logo()}<p>Original ideas. Connected engineering.</p></div><div>${routeLink('landing','Home')}${routeLink('pricing','Pricing')}${routeLink('dashboard','Dashboard')}${routeLink('profile','Profile')}</div><span>Studio preview · ${new Date().getFullYear()}<br>Concept tools. Human engineering judgment.</span></footer>`}
function landingPage(){return `${publicHeader()}<main class="landingMain"><section class="hero"><div class="heroCopy"><span class="launchTag"><i></i> THE WORKSPACE FOR ORIGINAL ENGINEERING</span><h1>From your first idea.<br>To your <em>next invention.</em></h1><p>Bring design, mechanics, electronics and evidence into one connected workspace. Explore how things work. Make something of your own.</p><div class="heroActions">${routeLink('signup','Start designing ↗','pbutton primary')}${routeLink('workspace','Explore the workspace →','textLink')}</div><div class="heroFine"><span>✓ Manual control</span><span>✓ Editable projects</span><span>✓ Free studio preview</span></div></div><div class="heroVisual"><div class="visualTop"><span><i></i> SLIDER-CRANK / CONCEPT STUDY</span><span>XY · mm</span></div><div class="heroMechanism">${mechanicalScene()}</div><div class="floatingSpec"><span>DESIGNED TO CONNECT</span><strong>One change.<br>Traceable consequences.</strong><div><span>Geometry</span><span>Motion</span><span>Evidence</span></div></div><div class="visualBottom"><span>◈ Parametric mechanism</span><span>45° / CONCEPT</span></div></div></section><div class="disciplineStrip"><span>ONE PROJECT. EVERY PERSPECTIVE.</span><b>Geometry</b><i>＋</i><b>Mechanisms</b><i>＋</i><b>Electronics</b><i>＋</i><b>Manufacturing</b><i>＋</i><b>Cost & evidence</b></div><section class="featureSection" id="features"><div class="sectionIntro"><span class="eyebrow">BUILT AROUND YOUR THINKING</span><h2>Less switching tools.<br>More connecting ideas.</h2><p>Start with a sketch. Refine a mechanism. Record what you learn. The project keeps the story together.</p></div><div class="featureBento"><article class="featureWide"><span class="featureNumber">01 / DESIGN</span><h3>Your dimensions.<br>Your decisions.</h3><p>Change stroke, rod length and operating speed. See a parameter-driven mechanism and inspect its motion.</p><div class="dimensionArt"><span>← &nbsp; 80 mm &nbsp; →</span><div><i></i><b></b><i></i></div></div>${routeLink('workspace','Explore design ↗','textLink')}</article><article><span class="featureNumber">02 / EVALUATE</span><div class="miniWave">⌁</div><h3>Understand the movement.</h3><p>Scrub the crank angle, inspect displacement, and export full-cycle motion samples.</p></article><article><span class="featureNumber">03 / DOCUMENT</span><div class="evidenceArt"><span>✓ Calculation recorded</span><span>↳ Linked to design</span><span>↺ Revision recoverable</span></div><h3>Keep the why.</h3><p>Track research notes, assumptions and project snapshots. See when calculated evidence becomes outdated.</p></article></div></section><section class="workflowSection"><div><span class="eyebrow">A PRACTICAL FIRST STEP</span><h2>Make a concept.<br>Then make it clearer.</h2><p>The current studio supports concept sketches, ideal calculations and planning records. Specialist CAD, live AI and engineering solvers are future integrations.</p>${routeLink('dashboard','See your dashboard ↗','pbutton')}</div><ol><li><span>01</span><div><h3>Create & explore</h3><p>Start an original project and sketch a concept.</p></div></li><li><span>02</span><div><h3>Change & evaluate</h3><p>Inspect dimensions, motion and basic electrical assumptions.</p></div></li><li><span>03</span><div><h3>Document & prepare</h3><p>Build your BOM, compare revisions and plan next steps.</p></div></li></ol></section><section class="closingCTA"><span class="eyebrow">MAKE IDEAS WORK.</span><h2>What will you create next?</h2><p>Your next engineering question deserves a workspace.</p>${routeLink('signup','Create your studio profile ↗','pbutton primary')}</section></main>${publicFooter()}`}
function accountPage(isSignup){return `${publicHeader()}<main class="authLayout"><section class="authStory"><span class="eyebrow">IDEAS BECOME SOMETHING HERE.</span><h1>Keep your curiosity.<br><em>Build your next idea.</em></h1><p>A connected place to design, understand and develop original engineering concepts.</p><div class="authArt">${mechanicalScene()}</div><div class="authStoryFoot"><span>01 / EXPLORE</span><span>02 / CREATE</span><span>03 / UNDERSTAND</span></div></section><section class="authFormSide"><span class="miniLabel">${isSignup?'YOUR WORKSPACE STARTS HERE':'GOOD TO SEE YOU AGAIN'}</span><h2>${isSignup?'Create your studio profile':'Log in to your studio'}</h2><p>${isSignup?'Set up your profile for this browser.':'Resume the profile saved on this device.'}</p>${previewNotice()}<form id="accountForm">${isSignup?field('accountName','Full name','','text'):''}<div class="field"><label for="accountEmail">Email address</label><input id="accountEmail" type="email" autocomplete="email" placeholder="you@example.com" required value="${esc(isSignup?'':account?.email||'')}"></div>${isSignup?'<div class="field"><label for="accountRole">Your focus</label><select id="accountRole"><option>Student / learner</option><option>Engineering researcher</option><option>Independent maker</option><option>Engineering team</option></select></div>':''}<p id="authError" class="formError" role="alert"></p><button class="primary full" type="submit">${isSignup?'Create preview profile':'Continue to preview dashboard'} ↗</button></form><div class="authSwitch">${isSignup?'Already have a local profile? '+routeLink('login','Log in'):'New to the studio? '+routeLink('signup','Create a profile')}</div><div class="localIdentity">⌑ Password-free preview. Email matching here is for navigation, not secure account authentication.</div></section></main>${publicFooter()}`}
const accountMenu=[['dashboard','▦','Overview'],['workspace','◇','Design workspace'],['premium','✧','Premium dashboard'],['billing','▤','Billing'],['profile','◉','My profile']];
function accountShell(content,title,kicker='YOUR CONNECTED WORKSPACE'){return `<div class="accountLayout"><aside class="accountSidebar">${logo()}<div class="sidebarLabel">WORKSPACE</div><nav aria-label="Account navigation">${accountMenu.map(([r,i,n])=>routeLink(r,`<span>${i}</span>${n}`,productRoute===r?'selected':'')).join('')}</nav><div class="premiumSidebar"><span>✧ ENGINEERING STUDIO</span><h3>Room for your next chapter.</h3><p>Explore the planned premium experience.</p>${routeLink('upgrade','Explore premium ↗')}</div><div class="accountSidebarFoot">${routeLink('landing','↗ Back to website')}<button data-logout>↪ ${signedIn?'End preview session':'Log in to preview'}</button></div></aside><div class="accountBody"><header class="accountHeader"><span>Workspace <i>/</i> ${esc(title)}</span><div>${routeLink('pricing','Plans & pricing')}${routeLink('profile',`<span class="avatar">${initials()}</span>`)}</div></header><main class="accountMain"><div class="accountHeading"><div><span class="eyebrow">${kicker}</span><h1>${esc(title)}</h1></div><span class="modeBadge">LOCAL PREVIEW</span></div>${content}</main><div class="accountFooter"><span>● Saved on this device</span><span>Engineering Design Studio · Preview</span></div></div></div>`}
function dashboardPage(premium=false){let revs=projects.reduce((n,p)=>n+p.revisions.length,0),notes=projects.reduce((n,p)=>n+p.notes.length,0);let body=`<section class="dashboardWelcome ${premium?'premiumWelcome':''}"><div><span class="miniLabel">${premium?'YOUR NEXT CHAPTER':'MAKE IDEAS WORK'}</span><h2>${premium?'A workspace with room to grow.':`Welcome${account?', '+esc(account.name.split(' ')[0]):' to your studio'}.`}</h2><p>${premium?'Preview your premium hub. Paid capabilities and pricing will be defined before launch.':'Pick up your last design, start a fresh idea, or explore what your project is telling you.'}</p><div class="heroActions">${routeLink('workspace','Open design workspace ↗','pbutton primary')}<button data-create-project>＋ New project</button></div></div><div class="welcomeSymbol">${premium?'✧':'◇'}<span>DESIGN · UNDERSTAND · CREATE</span></div></section>${premium?`<div class="premiumNotice"><span>✧</span><div><b>${demoOrders.some(o=>o.status==='demo_complete')?'Premium preview enabled':'Premium dashboard preview'}</b><p>This is a local preview, not an active paid subscription. No premium entitlements are granted.</p></div>${routeLink('billing','View billing →')}</div>`:''}<div class="dashboardMetrics">${metric('YOUR PROJECTS',projects.length,'Concepts in this browser')}${metric('SAVED REVISIONS',revs,'Recoverable project snapshots')}${metric('EVIDENCE RECORDS',notes,'Research and calculations')}${metric('CURRENT PLAN','Free','Studio preview access')}</div><section class="projectSection"><div class="sectionTitle"><div><h2>Your projects</h2><p>Original ideas, connected from the start.</p></div><div class="projectTools"><input id="projectSearch" placeholder="Search projects…" aria-label="Search projects" value="${esc(projectQuery)}"><button id="dashboardImport">↑ Import</button></div></div><div class="dashboardProjects" id="dashboardProjects">${projectCards()}</div></section>${premium?`<section class="premiumModules"><div class="sectionTitle"><div><h2>Shape the premium studio</h2><p>These product areas are awaiting your feature definitions.</p></div><span class="tag">PLANNED</span></div><div class="premiumModuleGrid">${[['◇','Design depth'],['⌁','Engineering evaluation'],['◫','Team & project workflows']].map(([i,n])=>`<article><span>${i}</span><h3>${n}</h3><p>Premium capabilities have not been specified yet.</p><small>Feature scope to be defined</small></article>`).join('')}</div></section>`:`<div class="dashboardBottom"><section class="card pageCard"><span class="eyebrow">SUGGESTED NEXT STEP</span><h2 style="margin-top:15px">Keep a record of the why.</h2><p>Save a revision before changing your parameters. Add an evidence note when you learn something new.</p>${routeLink('workspace','Continue your design →','textLink')}</section><section class="premiumCallout"><span>✧ PLANNING FOR WHAT’S NEXT</span><h2>Explore the premium experience.</h2><p>Preview the upgrade journey while the paid feature set is being defined.</p>${routeLink('upgrade','View upgrade options ↗','pbutton')}</section></div>`}`;return accountShell(body,premium?'Premium dashboard':'Dashboard')}
function projectCards(){const filtered=projects.filter(p=>p.name.toLowerCase().includes(projectQuery.toLowerCase()));return filtered.map(p=>`<article class="dashboardProject"><div class="projectDrawing"><svg viewBox="0 0 240 100" aria-hidden="true"><path d="M30 75H210" stroke="#bac8ab"/><circle cx="72" cy="50" r="27" fill="#e3ebda" stroke="#8ca37a"/><path d="M72 50L84 30L166 50" fill="none" stroke="#8ca37a" stroke-width="5"/><rect x="153" y="35" width="32" height="30" rx="3" fill="#d5e1c8" stroke="#8ca37a"/><circle cx="72" cy="50" r="4" fill="#789564"/></svg><span>CONCEPT</span></div><div class="projectDetails"><h3>${esc(p.name)}</h3><p>${esc(p.kind||'Engineering concept')}</p><div><span>${p.parts.length} parts · ${p.revisions.length} revisions</span><button data-open-project="${esc(p.id)}">Open ↗</button></div></div></article>`).join('')||'<div class="empty">No projects match your search.</div>'}
function profilePage(){return accountShell(`<div class="profileGrid"><section class="card profileIdentity"><span class="largeAvatar">${initials()}</span><h2>${esc(account?.name||'Your studio profile')}</h2><p>${esc(account?.role||'Engineering explorer')}</p><span class="pill">FREE STUDIO PREVIEW</span><hr><p>Profile information is stored locally in this browser.</p>${routeLink('billing','Manage billing →','textLink')}</section><section class="card pageCard"><div class="sectionTitle"><h2>Personal information</h2><span class="tiny">LOCAL PROFILE</span></div><form id="profileForm"><div class="row">${field('profileName','Full name',account?.name||'')}<div class="field"><label for="profileEmail">Email address</label><input id="profileEmail" type="email" value="${esc(account?.email||'')}" required></div></div>${field('profileOrganization','Organization / university',account?.organization||'')}<div class="row"><div class="field"><label for="profileRole">Focus</label><select id="profileRole">${['Student / learner','Engineering researcher','Independent maker','Engineering team'].map(r=>`<option ${account?.role===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label for="profileUnits">Preferred display units</label><input id="profileUnits" value="Metric · mm / kg / INR" disabled></div></div><div class="field"><label for="profileBio">About your work</label><textarea id="profileBio" maxlength="1000" placeholder="What are you curious about building?">${esc(account?.bio||'')}</textarea></div><button class="primary" type="submit">Save profile ↗</button><p id="profileStatus" role="status" class="tiny"></p></form></section></div><div class="accountInfo"><h3>Account & access</h3><p>The published site currently uses ChatGPT sign-in for owner-only access. This profile does not create an additional secure account. Production account registration, password reset and cross-device data need an authentication backend.</p><button data-logout class="sessionButton">End preview session →</button></div>`,'My profile','YOUR SPACE. YOUR DETAILS.')}
function planCards(upgrade=false){return `<div class="planGrid"><article class="planCard"><span class="planIcon">◇</span><h2>Studio Free</h2><p>A place to explore your next idea.</p><div class="planPrice">₹0 <small>/ studio preview</small></div><div class="planCaption">Current browser-local tools</div>${routeLink('dashboard','Explore free studio →','pbutton')}<ul><li>Project workspace & concept sketches</li><li>Ideal motion and circuit calculations</li><li>Editable BOM & planning costs</li><li>Research notes & revision snapshots</li><li>JSON, CSV and SVG exports</li></ul></article><article class="planCard featuredPlan"><div class="planRibbon">THE NEXT CHAPTER</div><span class="planIcon">✧</span><h2>Studio Premium</h2><p>A paid tier shaped around your needs.</p><div class="planPrice pendingPrice">To be announced</div><div class="planCaption">${annual?'Annual':'Monthly'} pricing is not set</div>${routeLink(upgrade?'checkout':'upgrade',upgrade?'Preview checkout →':'Explore premium ↗','pbutton primary')}<ul><li>Paid feature set to be defined</li><li>No premium limits configured yet</li><li>Preview the complete upgrade flow</li><li>No payment collected in this preview</li></ul><div class="planFoot">Premium preview does not unlock paid features.</div></article></div>`}
function pricingPage(upgrade=false){return `${publicHeader()}<main class="pricingMain"><div class="pricingIntro"><span class="launchTag">${upgrade?'YOUR WORKSPACE, WITH MORE POSSIBILITY':'START WITH CURIOSITY'}</span><h1>${upgrade?'Your next chapter starts here.':'A plan for your next idea.'}</h1><p>Explore the studio today. Premium features and final prices will be announced before paid access launches.</p><div class="billingToggle" aria-label="Billing period"><button data-period="monthly" class="${!annual?'selected':''}">Monthly</button><button data-period="annual" class="${annual?'selected':''}">Annually</button></div></div>${planCards(upgrade)}<section class="pricingCompare"><h2>Know exactly what you’re choosing.</h2><div class="tableWrap"><table><thead><tr><th>WORKSPACE CAPABILITY</th><th>FREE PREVIEW</th><th>PREMIUM</th></tr></thead><tbody>${[['Concept design tools','Included','Scope to be defined'],['BOM, evidence & local revisions','Included','Scope to be defined'],['Project storage','This browser','To be defined'],['Live AI / specialist CAD solvers','Not connected','Not committed'],['Billing','No charge','Not launched']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="faqSection"><h2>A few things to know.</h2>${[['Can I start without paying?','Yes. The current studio preview is free and saves project information in this browser. Export a project JSON file to keep a backup.'],['What is included in Premium?','The paid feature set has not been defined yet. The Premium dashboard and checkout are previews of the future product flow.'],['Will checkout charge me?','No. Checkout is a local simulation. It collects no card details and creates only a clearly labeled demo receipt.'],['Can I access my projects on another device?','Not automatically in this version. Export and import project JSON files to move your work. Cloud project storage requires further integration.']].map(([q,a])=>`<details><summary>${q}<span>＋</span></summary><p>${a}</p></details>`).join('')}</section></main>${publicFooter()}`}
function checkoutPage(){return `${publicHeader()}<main class="checkoutMain"><div class="checkoutIntro"><span class="eyebrow">EXPLORE THE UPGRADE JOURNEY</span><h1>Checkout preview</h1><p>A clear view of what comes next. No real payment is processed.</p></div><div class="checkoutSteps"><span class="done">01 / Choose plan</span><i></i><span class="active">02 / Review</span><i></i><span>03 / Confirmation</span></div><div class="checkoutGrid"><section class="card pageCard"><h2>Review your upgrade</h2><p>Preview the Premium checkout experience using your local profile.</p><div class="checkoutPreview"><span>⌑</span><div><h3>Simulation mode</h3><p>No card, UPI, bank or payment details are collected. No subscription is created.</p></div></div><form id="checkoutForm">${field('checkoutName','Name',account?.name||'')}<div class="field"><label for="checkoutEmail">Email address</label><input id="checkoutEmail" type="email" value="${esc(account?.email||'')}" required></div><div class="field"><label for="checkoutPeriod">Preferred billing period</label><select id="checkoutPeriod"><option value="monthly" ${!annual?'selected':''}>Monthly · pricing to be announced</option><option value="annual" ${annual?'selected':''}>Annually · pricing to be announced</option></select></div><label class="demoConsent"><input type="checkbox" id="demoConsent" required><span>I understand this is a demo checkout and no payment or subscription will be created.</span></label><button class="primary full" id="completeDemo" type="submit">Complete demo checkout →</button></form><p class="tiny" style="margin-top:16px">Your details and demo receipt stay in this browser.</p></section><aside class="orderSummary"><span class="eyebrow">ORDER SUMMARY · PREVIEW</span><div class="orderPlan"><span>✧</span><div><h2>Studio Premium</h2><p>Feature scope to be defined</p></div></div><div class="summaryLine"><span>Subscription price</span><b>Not announced</b></div><div class="summaryLine"><span>Taxes & billing</span><b>Not configured</b></div><div class="summaryLine totalLine"><span>Charged today</span><strong>₹0.00</strong></div><div class="note">This amount represents a no-charge simulation, not the price of Premium.</div><ul><li>✓ No card details required</li><li>✓ No real payment</li><li>✓ No automatic renewal</li></ul>${routeLink('pricing','← Back to plans','textLink')}</aside></div></main>${publicFooter()}`}
function confirmationPage(){const order=demoOrders.at(-1);return `${publicHeader()}<main class="confirmationMain"><div class="confirmationIcon">✓</div><span class="eyebrow">${order?'DEMO CHECKOUT COMPLETE':'PAYMENT CONFIRMATION PREVIEW'}</span><h1>${order?'You’ve explored the next step.':'Your confirmation will appear here.'}</h1><p>${order?'Your demo receipt is ready. No money was charged, no payment was received, and no paid subscription was activated.':'Complete the demo checkout to preview a receipt and the next step into the Premium dashboard.'}</p><section class="confirmationReceipt"><div><span>PLAN PREVIEW</span><b>Studio Premium</b></div><div><span>STATUS</span><b>${order?'Demo complete':'Not started'}</b></div><div><span>AMOUNT CHARGED</span><b>₹0.00</b></div>${order?`<div><span>DEMO RECEIPT</span><b>${esc(order.id)}</b></div><div><span>CREATED</span><b>${esc(new Date(order.date).toLocaleString())}</b></div>`:''}</section><div class="heroActions">${routeLink(order?'premium':'checkout',order?'Explore Premium dashboard ↗':'Try demo checkout →','pbutton primary')}${order?'<button id="downloadReceipt">↓ Download demo receipt</button>':''}</div><div class="confirmationLinks">${routeLink('billing','View billing')}${routeLink('dashboard','Back to dashboard')}</div></main>${publicFooter()}`}
function billingPage(){return accountShell(`<div class="billingTop"><section class="card pageCard"><span class="eyebrow">CURRENT PLAN</span><div class="currentPlan"><div><h2>Studio Free</h2><p>Your free, browser-local studio preview.</p></div><span class="pill">FREE PREVIEW</span></div><div class="planBilling"><strong>₹0<small> / current preview</small></strong><span>No active paid subscription</span></div>${routeLink('upgrade','Explore Premium ↗','pbutton primary')}</section><section class="card pageCard"><span class="eyebrow">PAYMENT METHOD</span><div class="noPayment">▱</div><h2>No payment method connected</h2><p>Payment collection is not configured. Card and bank information are not stored or requested.</p><span class="tiny">Production billing integration pending</span></section></div><section class="card pageCard receiptSection"><div class="sectionTitle"><div><h2>Demo receipt history</h2><p>Preview records only. These are not tax invoices or evidence of payment.</p></div><span class="tag">LOCAL RECORDS</span></div>${demoOrders.length?`<div class="tableWrap"><table><thead><tr><th>RECEIPT</th><th>DATE</th><th>PLAN</th><th>AMOUNT CHARGED</th><th>STATUS</th><th></th></tr></thead><tbody>${[...demoOrders].reverse().map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(new Date(o.date).toLocaleDateString())}</td><td>Premium preview</td><td>₹0.00</td><td><span class="pill">DEMO ONLY</span></td><td><button data-receipt="${esc(o.id)}">Download ↓</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><span class="emptyReceipt">▤</span><h3>No demo receipts yet</h3><p>Preview checkout to see how this billing history will work.</p>'+routeLink('checkout','Explore checkout →','textLink')+'</div>'}</section><div class="accountInfo"><h3>No renewal or cancellation needed</h3><p>There is no active paid subscription in this preview. A production payment provider, confirmed pricing and server-verified entitlements are required before billing can launch.</p></div>`,'Billing','EVERY DETAIL, IN ONE PLACE.')}
function receiptDownload(order){if(!order)return;download(order.id+'.txt',`ENGINEERING DESIGN STUDIO\nDEMO RECEIPT — NOT A PAYMENT RECEIPT OR TAX INVOICE\n\nReference: ${order.id}\nCreated: ${new Date(order.date).toLocaleString()}\nPlan: Studio Premium preview\nBilling preference: ${order.period}\nCharged: INR 0.00\nStatus: Demo complete\n\nNo payment was received. No subscription or paid entitlement was created.\n`,'text/plain')}
function openProductProject(id){const p=projects.find(p=>p.id===id);if(p)current=p;location.hash='/workspace'}
function bindProduct(){document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{annual=b.dataset.period==='annual';showProductRoute()});document.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=()=>openProductProject(b.dataset.openProject));document.querySelectorAll('[data-create-project]').forEach(b=>b.onclick=()=>{location.hash='/workspace';newProject()});document.querySelectorAll('[data-logout]').forEach(b=>b.onclick=()=>{signedIn=false;sessionStorage.removeItem('studio-demo-session');location.hash='/login'});if($('#dashboardImport'))$('#dashboardImport').onclick=()=>{location.hash='/workspace';importProject()};if($('#projectSearch'))$('#projectSearch').oninput=e=>{projectQuery=e.target.value;$('#dashboardProjects').innerHTML=projectCards();document.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=()=>openProductProject(b.dataset.openProject))};if($('#accountForm')){$('#accountForm').onsubmit=e=>{e.preventDefault();const email=$('#accountEmail').value.trim().toLowerCase();if(productRoute==='signup'){const name=$('#accountName').value.trim();if(!name){$('#authError').textContent='Please enter your name.';return}if(account&&account.email!==email){$('#authError').textContent='A different preview profile is already saved here. Use Profile to edit it, or log in with its email.';return}account={...account,name,email,role:$('#accountRole').value};localStorage.setItem('studio-profile-v1',JSON.stringify(account))}else if(!account||email!==account.email){$('#authError').textContent='No matching profile on this device. Create a preview profile first.';return}signedIn=true;sessionStorage.setItem('studio-demo-session','active');location.hash='/dashboard'};if($('#accountName'))$('#accountName').required=true}if($('#profileForm')){$('#profileName').required=true;$('#profileForm').onsubmit=e=>{e.preventDefault();let name=$('#profileName').value.trim();if(!name)return;account={name,email:$('#profileEmail').value.trim().toLowerCase(),role:$('#profileRole').value,organization:$('#profileOrganization').value.trim(),bio:$('#profileBio').value.trim()};localStorage.setItem('studio-profile-v1',JSON.stringify(account));showProductRoute();$('#profileStatus').textContent='Profile saved on this device.'}}if($('#checkoutForm')){$('#checkoutName').required=true;$('#checkoutForm').onsubmit=e=>{e.preventDefault();if(!$('#checkoutName').value.trim())return;const button=$('#completeDemo');button.disabled=true;const order={id:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),date:new Date().toISOString(),period:$('#checkoutPeriod').value,status:'demo_complete',amount:0};demoOrders.push(order);try{localStorage.setItem('studio-demo-orders',JSON.stringify(demoOrders))}catch{demoOrders.pop();button.disabled=false;toast('Could not save the demo receipt. Browser storage may be full.');return}location.hash='/confirmation'}}if($('#downloadReceipt'))$('#downloadReceipt').onclick=()=>receiptDownload(demoOrders.at(-1));document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>receiptDownload(demoOrders.find(o=>o.id===b.dataset.receipt)))}
function showProductRoute(){const hash=location.hash.replace(/^#\/?/,'');const name=hash.split(/[?#]/)[0]||'landing';if(name==='workspace'){document.body.classList.remove('productMode');productRoot.innerHTML='';page='design';render();document.title='Design workspace · Engineering Studio';window.scrollTo(0,0);return}productRoute=productRoutes.includes(name)?name:'landing';document.body.classList.add('productMode');playback=false;cancelAnimationFrame(raf);const renderers={landing:landingPage,signup:()=>accountPage(true),login:()=>accountPage(false),dashboard:()=>dashboardPage(false),profile:profilePage,pricing:()=>pricingPage(false),upgrade:()=>pricingPage(true),checkout:checkoutPage,confirmation:confirmationPage,billing:billingPage,premium:()=>dashboardPage(true)};productRoot.innerHTML=renderers[productRoute]();document.title=({landing:'Design real things',signup:'Sign up',login:'Log in',dashboard:'Dashboard',profile:'Profile',pricing:'Pricing',upgrade:'Upgrade',checkout:'Checkout preview',confirmation:'Payment confirmation preview',billing:'Billing',premium:'Premium dashboard'}[productRoute])+' · Engineering Studio';bindProduct();window.scrollTo(0,0);if(hash.includes('#features'))$('#features')?.scrollIntoView({behavior:'smooth'})}
document.querySelector('.rail .brand').href='#/landing';document.querySelector('.rail .brand').insertAdjacentHTML('afterend','<a class="workspaceAccountShortcut" href="#/dashboard" aria-label="Account dashboard" title="Account dashboard">▦</a>');document.querySelector('.rail .profile').outerHTML='<a class="workspaceProfile" href="#/dashboard">▦ Account dashboard ↗</a>';document.querySelector('.rail .workspace').outerHTML='<a class="workspace" href="#/dashboard">← BACK TO DASHBOARD</a>';window.addEventListener('hashchange',showProductRoute);showProductRoute();
